{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "CC-292, the closest structural analogue, showed excellent oral bioavailability in a human Phase IA study; its pyrimidine-diamine and anilino-ether features are shared with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Imatinib, a pyrimidine-diamine kinase inhibitor with a basic amine side chain, has a mean absolute oral bioavailability of 98% in patients, supporting high F for the query's similar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Pazopanib, which shares the pyrimidine-diamine and sulfonamide motifs with the query, has an absolute oral bioavailability of 21.4% in cancer patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Enasidenib, a heteroaromatic amine drug, has an absolute oral bioavailability of 57.2% in humans, supporting high oral absorption for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Zongertinib, a pyrimidine-based kinase inhibitor with a basic amine substituent, was predicted to have 41% oral bioavailability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Raloxifene has only 2% oral bioavailability in humans, but this is attributed to extensive intestinal and hepatic glucuronidation of phenolic groups, which are absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a pyrimidine-diamine kinase-inhibitor-like molecule with a basic pyrrolidinylethoxy side chain and a tert-butylsulfamoyl group, and it lacks the phenolic glucuronidation sites responsible for the very low F of raloxifene and bazedoxifene. Multiple structurally relevant kinase inhibitors with human absolute bioavailability data—CC-292, imatinib, pazopanib, enasidenib, and zongertinib—support F >= 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "All retrieved analogues have Morgan similarity below 0.4, limiting quantitative transferability.",
    "Pazopanib's F is borderline near the 20% threshold, and solubility/efflux behavior of the query is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

